INSERT INTO criteria_issues (id, category_id, code, title, sort) VALUES (1,1,'1.1','การกำหนดนโยบายสิ่งแวดล้อม',0);
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (1,1,'1.1.1','มีบริบทองค์กรและขอบเขตของการจัดการสิ่งแวดล้อมในสำนักงาน',0);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (1,0,'(1) มีการกำหนดขอบเขตพื้นที่ของสำนักงาน');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (1,1,'(2) มีการกำหนดขอบเขตกิจกรรมของสำนักงาน');
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (2,1,'1.1.2','นโยบายด้านสิ่งแวดล้อมที่สอดคล้องและครอบคลุมประเด็นตามเกณฑ์สำนักงานสีเขียวโดยแสดงความมุ่งมั่นอย่างต่อเนื่อง ดังนี้',1);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (2,0,'(1) การปรับปรุงระบบการจัดการสิ่งแวดล้อมอย่างต่อเนื่อง');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (2,1,'(2) การควบคุม ป้องกัน ลดผลกระทบด้านการใช้ทรัพยากร พลังงาน และ มลพิษ/ของเสีย รวมไปถึงการจัดซื้อ จัดจ้าง และบริการที่เป็นมิตรกับสิ่งแวดล้อม เพื่อนำไปสู่การลดการปล่อยก๊าซเรือนกระจก');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (2,2,'(3) การปฏิบัติตามกฎหมายและเกณฑ์การเป็นสำนักงานสีเขียวของกรมส่งเสริมคุณภาพสิ่งแวดล้อม');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (2,3,'(4) การสร้างความรู้และความตระหนักด้านสิ่งแวดล้อมกับผู้เกี่ยวข้อง');
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (3,1,'1.1.3','การกำหนดนโยบายสิ่งแวดล้อมจากผู้บริหารระดับสูง',2);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (3,0,'(1) นโยบายสิ่งแวดล้อมจะต้องได้รับการอนุมัติจากผู้บริหารสูงสุด หรือผู้ที่ได้รับมอบอำนาจ');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (3,1,'(2) มีการระบุวันที่การประกาศใช้นโยบายสิ่งแวดล้อมอย่างชัดเจน');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (3,2,'(3) ผู้บริหารหรือผู้มีอำนาจจะต้องสามารถอธิบายถึงวัตถุประสงค์และจุดมุ่งหมายด้านสิ่งแวดล้อมของสำนักงาน');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (3,3,'(4) ผู้บริหารหรือผู้มีอำนาจจะต้องมีส่วนในการติดตามผลการปฏิบัติตามนโยบายสิ่งแวดล้อมของสำนักงาน');
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (4,1,'1.1.4','มีการกำหนดแผนการดำเนินงานสำนักงานสีเขียวประจำปี',3);
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (5,1,'1.1.5','มีการกำหนดเป้าหมาย และตัวชี้วัดที่ชัดเจนด้านการใช้ทรัพยากร พลังงาน และของเสีย และปริมาณก๊าซเรือนกระจก',4);
INSERT INTO criteria_issues (id, category_id, code, title, sort) VALUES (2,1,'1.2','คณะทำงานด้านสิ่งแวดล้อม',1);
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (6,2,'1.2.1','มีการแต่งตั้งคณะกรรมการหรือทีมงานด้านสิ่งแวดล้อม โดยมีแนวทางดำเนินงาน ดังนี้',0);
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (7,2,'1.2.2','ร้อยละของคณะกรรมการ หรือทีมงานด้านสิ่งแวดล้อมที่มีความเข้าใจในบทบาทและหน้าที่รับผิดชอบ',1);
INSERT INTO criteria_issues (id, category_id, code, title, sort) VALUES (3,1,'1.3','การระบุประเด็นปัญหาทรัพยากรและสิ่งแวดล้อม',2);
