INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (9,3,'1.3.2','การวิเคราะห์และแนวทางการแก้ไขปัญหาสิ่งแวดล้อมที่มีนัยสำคัญ',1);
INSERT INTO criteria_issues (id, category_id, code, title, sort) VALUES (4,1,'1.4','กฎหมายและข้อกำหนดอื่นๆ ที่เกี่ยวข้อง',3);
