INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (10,0,'(1) ผู้รับผิดชอบมีความเข้าใจในการรวบรวมกฎหมาย สิ่งแวดล้อมที่เกี่ยวข้อง');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (10,1,'(2) จัดทำรายการกฎหมายที่ครอบคลุมปัญหา สิ่งแวดล้อมและบริบทของสำนักงาน');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (10,2,'(3) สามารถระบุแหล่งที่มาของกฎหมายและข้อกำหนด ข้อกำหนดอื่น ๆ ที่เกี่ยวข้องได้');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (10,3,'(4) สามารถระบุความเกี่ยวข้องของกฎหมายกับประเด็น ปัญหาสิ่งแวดล้อมได้');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (10,4,'(5) กฎหมายสิ่งแวดล้อมและความปลอดภัยที่เกี่ยวข้อง จะต้องเป็นปัจจุบัน');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (10,5,'(6) มีการรวบรวมและทบทวนกฎหมายอย่างน้อยปีละ 1 ครั้ง');
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (11,4,'1.4.2','ประเมินความสอดคล้องของกฎหมายกับการดำเนินงานการจัดการสิ่งแวดล้อมของสำนักงาน โดยมีการดำเนินการดังนี้',1);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (11,0,'(1) ผู้รับผิดชอบมีความเข้าใจในการประเมินความสอดคล้องของกฎหมายกับการดำเนินงานการจัดการสิ่งแวดล้อม');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (11,1,'(2) มีการประเมินความสอดคล้องของกฎหมาย ครบถ้วน');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (11,2,'(3) มีการอ้างอิงหลักฐานการปฏิบัติตามกฎหมายอย่างครบถ้วนและถูกต้อง กรณีที่พบว่าการดำเนินงานไม่สอดคล้องกับกฎหมาย จะต้องมีการวิเคราะห์สาเหตุ และกำหนดแนวทางการแก้ไข (ถ้ามี)');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (11,3,'(4) มีการกำหนดความถี่ในการประเมินความสอดคล้องของกฎหมายอย่างน้อยปีละ 1 ครั้ง ที่เหมาะสมและมีการปฏิบัติตามที่กำหนดได้');
INSERT INTO criteria_issues (id, category_id, code, title, sort) VALUES (5,1,'1.5','ข้อมูลก๊าซเรือนกระจก',4);
