INSERT INTO criteria_issues (id, category_id, code, title, sort) VALUES (6,1,'1.6','แผนงานโครงการที่นำไปสู่การปรับปรุงอย่างต่อเนื่อง',5);
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (15,6,'1.6.1','การกำหนดวัตถุประสงค์ เป้าหมาย และโครงการสิ่งแวดล้อม จะต้องมีการดำเนินการดังนี้',0);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (15,0,'(1) วัตถุประสงค์ เป้าหมาย จะต้องสอดคล้องกับนโยบายสิ่งแวดล้อม หรือปัญหาสิ่งแวดล้อมที่มีนัยสำคัญ หรือกฎหมายสิ่งแวดล้อม');
