INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (16,6,'1.6.2','ผลสำเร็จของวัตถุประสงค์และเป้าหมาย แนวทางการปรับปรุงอย่างต่อเนื่องและยั่งยืน',1);
