INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (16,3,'(4) มีการติดตามความก้าวหน้าของโครงการ');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (16,4,'(5) ดำเนินการเสร็จสิ้นและบรรลุตามเป้าหมายที่กาหนด / กรณีที่ไม่บรรลุเป้าหมายมีการทบทวนเพื่อหาสาเหตุและแนวทางแก้ไข');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (16,5,'(6) มีการกำหนดแนวทางเพื่อให้เกิดความต่อเนื่องและยั่งยืนหลังบรรลุเป้าหมายตามที่กำหนด');
INSERT INTO criteria_issues (id, category_id, code, title, sort) VALUES (7,1,'1.7','การตรวจประเมินสำนักงานสีเขียวภายในสำนักงาน (สำหรับหน่วยงานต่ออายุและขอยกระดับสำนักงานสีเขียว)',6);
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (17,7,'1.7.1','การวางแผนและดำเนินการตรวจประเมินสำนักงานสีเขียวภายในสำนักงาน',0);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (17,0,'(1) มีการแต่งตั้งคณะกรรมการตรวจประเมินสำนักงานสีเขียวภายในสำนักงาน ประกอบด้วย หัวหน้าผู้ตรวจประเมินและผู้ตรวจประเมิน ซึ่งจะต้องผ่านการฝึกอบรมหลักสูตรการดำเนินงานสำนักงานสีเขียว และหลักสูตรการตรวจประเมินสำนักงานสีเขียว');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (17,1,'(2) มีการกำหนดความถี่ในการตรวจประเมินสำนักงานสีเขียวภายในสำนักงานอย่างน้อยปีละ 1 ครั้ง');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (17,2,'(3) มีการจัดทำข้อกำหนดการตรวจประเมินภายในครอบคลุมทุกหมวด');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (17,3,'(4) กำหนดผู้ตรวจประเมินภายในแต่ละหมวดมีความเพียงพอและเหมาะสม มีความเป็นอิสระในการตรวจประเมินอย่างชัดเจน');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (17,4,'(5) การดำเนินการตรวจประเมินสำนักงานสีเขียวภายในสำนักงานครบถ้วนทุกหมวด');
INSERT INTO criteria_issues (id, category_id, code, title, sort) VALUES (8,1,'1.8','การทบทวนฝ่ายบริหาร',7);
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (18,8,'1.8.1','การกำหนดองค์ประชุมทบทวนฝ่ายบริหาร',0);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (18,0,'(1) มีผู้บริหารเข้าร่วมประชุม');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (18,1,'(2) มีตัวแทนของแต่ละฝ่าย/แผนก/ส่วนงานที่มีความเกี่ยวข้องกับการดำเนินงานในแต่ละหมวดเข้าร่วมประชุม');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (18,2,'(3) จำนวนผู้เข้าร่วมการประชุมจะต้องมากกว่าร้อยละ 75 ของจำนวนผู้ที่เป็นคณะกรรมการสำนักงานสีเขียว พร้อมหลักฐานการลงนามเข้าร่วมประชุม');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (18,3,'(4) หากผู้ที่จะต้องเข้าประชุมไม่สามารถเข้าร่วมได้ จะต้องมีวิธีการรายงานผลการประชุมให้รับทราบ พร้อมรับข้อเสนอแนะ');
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (19,8,'1.8.2','มีการกำหนดวาระการประชุม และทำการประชุมทบทวนฝ่ายบริหารดังนี้',1);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (19,0,'(1) มีการประชุมทบทวนฝ่ายบริหารอย่างน้อยปีละ 1 ครั้ง');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (19,1,'(2) วาระที่ 1 การติดตามผลการประชุมทบทวนฝ่ายบริหารที่ผ่านมา');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (19,2,'(3) วาระที่ 2 นโยบายสิ่งแวดล้อม');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (19,3,'(4) วาระที่ 3 ความมีประสิทธิภาพของคณะกรรมการหรือทีมงานด้านสิ่งแวดล้อม (ความเพียงพอและความเหมาะสม)');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (19,4,'(5) วาระที่ 4 การติดตามผลการดำเนินงานด้านสิ่งแวดล้อม การสื่อสารและข้อคิดเห็นด้านสิ่งแวดล้อม การปฏิบัติตามกฎหมาย รวมถึงแนวทางการแก้ไขปรับปรุงและพัฒนา');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (19,5,'(6) วาระที่ 5 การเปลี่ยนแปลงที่จะส่งผลกระทบต่อความสำเร็จในการดำเนินงานด้านสิ่งแวดล้อม');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (19,6,'(7) วาระที่ 6 ข้อเสนอแนะจากที่ประชุม และวิสัยทัศน์ แนวคิดของผู้บริหารของการดำเนินงานสำนักงานสีเขียวอย่างต่อเนื่อง');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (19,7,'(8) จัดทำรายงานการประชุมทบทวนฝ่ายบริหาร และภาพถ่ายที่แสดงให้เห็นว่ามีการประชุมจริง');
INSERT INTO criteria_issues (id, category_id, code, title, sort) VALUES (9,2,'2.1','การอบรมให้ความรู้และประเมินความเข้าใจ',0);
