INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (35,2,'(3) สรุปการบรรลุ / ไม่บรรลุ');
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (36,13,'3.3.3','การปฏิบัติตามมาตรการประหยัดกระดาษในพื้นที่ทำงาน (ประเมินจากพฤติกรรมของบุคลากรในพื้นที่)',2);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (36,0,'(1) ในการสำรวจพื้นที่สำนักงานมีการปฏิบัติตามมาตรการและไม่พบการใช้กระดาษสิ้นเปลือง');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (36,1,'(2) สัมภาษณ์บุคลากรถึงมาตรการหรือแนวทางใช้กระดาษของหน่วยงานได้และนำไปปฏิบัติหรือปรับเปลี่ยนพฤติกรรม');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (36,2,'(3) สัมภาษณ์บุคลากรถึงการใช้กระดาษของหน่วยงาน (สาเหตุของการบรรลุ/ไม่บรรลุ เพราะอะไร)');
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (37,13,'3.3.4','มาตรการหรือแนวทางการใช้หมึกพิมพ์ อุปกรณ์เครื่องเขียน วัสดุอุปกรณ์เหมาะสมกับสำนักงาน จะต้องประกอบไปด้วย รายละเอียดดังนี้',3);
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (38,13,'3.3.5','การดำเนินตามมาตรการประหยัดการใช้หมึกพิมพ์ อุปกรณ์เครื่องเขียน วัสดุอุปกรณ์สำนักงาน (ประเมินจากพฤติกรรมของบุคลากรในพื้นที่)',4);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (38,0,'(1) ในการสำรวจพื้นที่สำนักงานมีการปฏิบัติตามมาตรการการประหยัดการใช้หมึกพิมพ์ อุปกรณ์เครื่องเขียนวัสดุอุปกรณ์สำนักงาน และไม่พบการใช้สิ้นเปลือง');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (38,1,'(2) สัมภาษณ์บุคลากรถึงมาตรการหรือแนวทางประหยัดการใช้หมึกพิมพ์อุปกรณ์เครื่องเขียน วัสดุอุปกรณ์สำนักงาน และนำไปปฏิบัติหรือปรับเปลี่ยนพฤติกรรม');
INSERT INTO criteria_issues (id, category_id, code, title, sort) VALUES (14,3,'3.4','การประชุมและการจัดนิทรรศการ',3);
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (39,14,'3.4.1','มาตรการหรือแนวทางการจัดการประชุมและนิทรรศการที่เป็นมิตรกับสิ่งแวดล้อม',0);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (39,0,'(1) กำหนดมาตรการจัดการประชุมและนิทรรศการที่เป็นมิตรกับสิ่งแวดล้อมในรูปแบบ Green Meeting');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (39,1,'(2) มีการประชุมผ่านระบบออนไลน์เพื่อลดการใช้พลังงานและทรัพยากร');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (39,2,'(3) มีการใช้เอกสารอิเล็กทรอนิกส์ หรือไฟล์ดิจิทัล ในการส่งหนังสือเชิญเข้าร่วมการประชุม การส่งเอกสาร/ข้อมูลการประชุม ได้แก่ QR code, Email,Social Network, Intranet เป็นต้น');
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (40,14,'3.4.2','การจัดการประชุมและนิทรรศการที่มีการใช้วัสดุที่เป็นมิตรกับสิ่งแวดล้อม ลดการใช้ทรัพยากรพลังงาน และลดของเสียที่เกิดขึ้น จะต้องดำเนินการ ดังนี้',1);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (40,0,'(2) ห้องประชุมหรือสถานที่จัดประชุมหรือพื้นที่จัดนิทรรศการไม่มีการตกแต่งด้วยวัสดุที่ใช้ครั้งเดียวแล้วทิ้งหรือวัสดุที่ย่อยสลายยาก เช่น โฟมหรือลดการใช้พลังงานได้ (เป็นการประชุม Out door) เป็นต้น');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (40,1,'(3) มีแนวทางปฏิบัติการใช้พลังงานหรือเครื่องใช้ไฟฟ้า ของการใช้ห้องประชุม');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (40,2,'(4) การจัดเตรียมอาหาร และเครื่องดื่มที่มีความเป็นมิตรกับสิ่งแวดล้อม ลดการใช้บรรจุภัณฑ์ที่ย่อยสลายยาก ลดปริมาณขยะที่เกิดขึ้น และต้องมีการคัดแยกขยะ');
INSERT INTO criteria_issues (id, category_id, code, title, sort) VALUES (15,4,'4.1','การจัดการของเสีย',0);
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (41,15,'4.1.1','มาตรการหรือแนวทางจัดการขยะที่เหมาะสมกับสำนักงาน มีการสร้างความตระหนัก และการมีส่วนร่วมของบุคลากร',0);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (41,0,'(1) กำหนดมาตรการหรือแนวทางจัดการขยะแต่ละประเภทของหน่วยงาน การลดขยะพลาสติกที่ใช้ครั้งเดียวทิ้ง (Single UsePlastic) เช่น แก้วพลาสติก หลอดพลาสติก ถุงหูหิ้ว กล่องบรรจุภัณฑ์ใส่อาหาร เป็นต้น');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (41,1,'(2) มีแผนในการลดปริมาณขยะในภาพรวม เพื่อมุ่งสู่ Zero waste');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (41,2,'(3) มีการประกาศเป็นองค์กรปลอดโฟม');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (41,3,'(4) มีการประกาศเจตนารมณ์หรือทำข้อตกลงร่วมกันในองค์กร');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (41,4,'(5) มีการรณรงค์สร้างการมีส่วนร่วมเพื่อลดขยะพลาสติกในองค์กร เช่นการใช้ถุงผ้า การใช้แก้วน้ำส่วนตัว');
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (42,15,'4.1.2','มีการดำเนินงานตามแนวทางการคัดแยก รวบรวม และกำจัดขยะอย่างเหมาะสม มีแนวทางการดำเนินงาน ดังนี้',1);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (42,0,'(1) มีการกำหนดจุดวางถังขยะบริเวณสำนักงานอย่างเหมาะสม และมีการคัดแยกขยะตามประเภทขยะที่เกิดขึ้นจากกิจกรรมภายในสำนักงาน');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (42,1,'(2) มีการติดป้ายบ่งชี้ประเภทขยะอย่างถูกต้องและชัดเจนทุกถัง');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (42,2,'(3) มีจุดพักขยะหรือโรงพักขยะที่เหมาะสมตามหลักวิชาการ โดยจะต้องมีพื้นที่รองรับขยะแต่ละประเภทจากข้อ (1) อย่างเพียงพอ');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (42,3,'(4) การสำรวจการทิ้งขยะแต่ละประเภทในสำนักงาน มีความถูกต้องทุกจุดที่สุ่มตรวจสอบ');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (42,4,'(5) มีการจัดทำเส้นทางการจัดการขยะแต่ละประเภทอย่างเหมาะสม และส่งขยะให้กับหน่วยงานที่รับดำเนินการ (สำนักงานเขต/ อปท.) หรือผู้รับจ้างที่ได้รับอนุญาตตามกฎหมาย');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (42,5,'(6) การติดตาม ตรวจสอบการกำจัดขยะของผู้รับจ้างให้มีการจัดการอย่างเหมาะสมตามหลักวิชาการ (กรณีส่งให้สำนักงานเขต / อปท.ให้ถือว่ามีการจัดการอย่างเหมาะสม)');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (42,6,'(7) ไม่มีการเผาขยะในบริเวณหรือพื้นที่ของสำนักงาน (ยกเว้นเตาเผาที่ได้รับการอนุญาตอย่างถูกต้อง)');
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (43,15,'4.1.3','การนำขยะกลับมาใช้ประโยชน์หรือนำกลับมาใช้ใหม่ ส่งผลให้ขยะที่จะส่งไปกำจัดมีปริมาณน้อยลง',2);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (43,0,'(1) มีการบันทึกข้อมูลปริมาณขยะแต่ละประเภทครบถ้วนทุกเดือน พร้อมแสดงผล');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (43,1,'(2) มีการวิเคราะห์ปริมาณขยะเทียบค่าเป้าหมายที่ได้กำหนดไว้ในหมวด 1 ข้อ 1.1.3');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (43,2,'(3) มีการนำขยะกลับมาใช้ประโยชน์หรือนำกลับมาใช้ใหม่ มากกว่าร้อยละ 50 ของปริมาณขยะทั้งหมดของหน่วยงานต่อเดือน หรือมีนวัตกรรมหรือมีการส่งขยะไปเป็นเชื้อเพลิงRDF');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (43,3,'(4) ปริมาณขยะที่ส่งกำจัด (ขยะทั่วไป) มีแนวโน้มลดลง');
INSERT INTO criteria_issues (id, category_id, code, title, sort) VALUES (16,4,'4.2','การจัดการน้ำเสีย',1);
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (44,16,'4.2.1','การจัดการน้ำเสียของสำนักงานและคุณภาพน้ำทิ้ง จะต้องอยู่ในมาตรฐานกฎหมายที่เกี่ยวข้อง โดยมีแนวทางดังนี้',0);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (44,0,'(1) การกำหนดผู้รับผิดชอบที่มีความรู้ความเข้าใจในการดูแลจัดการน้ำเสียของหน่วยงาน');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (44,1,'(2) หน่วยงานมีการบำบัดน้ำเสียอย่างเหมาะสมและมีประสิทธิภาพ ตามบริบทของหน่วยงาน เช่น มีตะแกรงดักเศษอาหาร อุปกรณ์บำบัดน้ำเสีย ถังดักไขมัน ระบบบำบัดน้ำเสีย เหมาะสมกับองค์ประกอบของน้ำเสีย');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (44,2,'(3) มีการบำบัดน้ำเสียครบทุกจุดที่มีการปล่อยน้ำเสีย และมีการบำบัดน้ำเสียของหน่วยงาน');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (44,3,'(4) ระบบบำบัดน้ำเสียอยู่ในสภาพพร้อมใช้งาน และมีผลการตรวจสอบคุณภาพน้ำทิ้งที่ อยู่ในเกณฑ์มาตรฐานตามที่กฎหมายกำหนดคำจำกัดความ การบำบัดน้ำเสียของหน่วยงาน เช่น อุปกรณ์บำบัดน้ำเสีย ถังดักไขมัน ระบบบำบัดน้ำเสีย เป็นต้น');
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (45,16,'4.2.2','การดูแลอุปกรณ์บำบัดน้ำเสีย โดยมีแนวทางดังนี้',1);
INSERT INTO criteria_issues (id, category_id, code, title, sort) VALUES (17,5,'5.1','อากาศในสำนักงาน',0);
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (46,17,'5.1.1','การควบคุมมลพิษทางอากาศในสำนักงาน',0);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (46,0,'(1) มีแผนการดูแลบำรุงรักษา ได้แก่ เครื่องปรับอากาศ เครื่องถ่ายเอกสาร เครื่องพิมพ์เอกสาร (Printer) พรมปูพื้นห้อง (ขึ้นอยู่กับสำนักงาน)');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (46,1,'(2) มีการกำหนดหน้าที่ความรับผิดชอบตามแผนการดูแลบำรุงรักษา');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (46,2,'(3) มีการปฏิบัติตามแผนที่กำหนดในข้อ (1)');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (46,3,'(4) มีการควบคุมมลพิษทางอากาศจากการปฏิบัติในข้อ (1)');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (46,4,'(5) การจัดวางเครื่องพิมพ์เอกสาร เครื่องถ่ายเอกสาร (Printer) ให้ห่างไกลผู้ปฏิบัติงาน');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (46,5,'(6) การควบคุมควันไอเสียรถยนต์บริเวณสำนักงาน เช่น ติดป้ายดับเครื่องยนต์');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (46,6,'(7) การป้องกันอันตรายจากการพ่นยากำจัดแมลง (ถ้ามี)');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (46,7,'(8) มีการสื่อสารหรือแจ้งให้ทราบถึงการเกิดมลพิษทางอากาศจากกิจกรรมต่าง ๆ เพื่อการเตรียมความพร้อมและระวังการได้รับอันตราย');
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (47,17,'5.1.2','มีการรณรงค์ไม่สูบบุหรี่หรือมี การกำหนดพื้นที่สูบบุหรี่ที่เหมาะสมและปฏิบัติตามที่กำหนด',1);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (47,0,'(1) มีการรณรงค์การไม่สูบบุหรี่');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (47,1,'(2) มีการติดสัญลักษณ์เขตปลอดบุหรี่');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (47,2,'(3) มีการติดสัญลักษณ์เขตสูบบุหรี่');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (47,3,'(4) เขตสูบบุหรี่จะต้องไม่อยู่ในบริเวณที่ก่อให้เกิดความเดือดร้อนรำคาญแก่ประชาชนที่อยู่บริเวณข้างเคียงไม่อยู่ในบริเวณทางเข้า – ออกของสถานที่ที่ให้มีการคุ้มครองสุขภาพ ของผู้ไม่สูบบุหรี่และไม่อยู่ในบริเวณที่เปิดเผยอันเป็นที่เห็นได้ชัดแก่ผู้มาใช้สถานที่นั้น');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (47,4,'(5) ไม่พบการสูบบุหรี่ หรือก้นบุหรี่นอกเขตสูบบุหรี่');
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (48,17,'5.1.3','การจัดการมลพิษทางอากาศจากการก่อสร้าง ปรับปรุง อาคารหรืออื่น ๆ ในสำนักงานที่ส่งผลต่อพนักงาน',2);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (48,0,'(1) กำหนดมาตรการรองรับเพื่อจัดการมลพิษทางอากาศจากการก่อสร้าง ปรับปรุงอาคาร');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (48,1,'(2) ปฏิบัติตามมาตรการที่ได้กำหนดในข้อ (1) แนวทางการกำหนดมาตรการมีดังนี้- มีพื้นที่ทำงานสำรองให้กับพนักงาน- มีที่กั้นเพื่อป้องกันมลพิษทางอากาศที่จะส่ง ผลกระทบกับพนักงานหรือผู้ที่เกี่ยวข้อง- มีการสื่อสารหรือติดป้ายแจ้งเตือนเพื่อการเตรียมความพร้อมและระวังการได้รับอันตราย');
INSERT INTO criteria_issues (id, category_id, code, title, sort) VALUES (18,5,'5.2','แสงในสำนักงาน',1);
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (49,18,'5.2.1','มีการตรวจวัดความเข้มของแสงสว่าง (โดยอุปกรณ์การตรวจวัดความเข้มของแสงสว่างที่ได้มาตรฐาน) และดำเนินการแก้ไขตามที่มาตรฐานกำหนด',0);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (49,0,'(1) มีการตรวจวัดความเข้มของแสงสว่างประจำปี พร้อมแสดงหลักฐานผลการตรวจวัดความเข้มของแสงสว่างเฉพาะจุดทำงานและพื้นที่ทำงาน');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (49,1,'(2) เครื่องวัดความเข้มของแสงสว่างจะต้องมีมาตรฐานและได้รับการสอบเทียบ(แสดงหลักฐานใบรับรอง)');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (49,2,'(3) ผลการตรวจวัดจะต้องเป็นไปตามมาตรฐานกฎหมายกำหนด');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (49,3,'(4) ผู้ที่ตรวจวัดความเข้มของแสงสว่างจะต้องเป็นไปตามที่กฎหมายกำหนด');
INSERT INTO criteria_issues (id, category_id, code, title, sort) VALUES (19,5,'5.3','เสียง',2);
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (50,19,'5.3.1','การควบคุมมลพิษทางเสียงภายในอาคารสำนักงาน',0);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (50,0,'(1) กำหนดมาตรการรองรับเพื่อจัดการเสียงดังที่มาจากภายในสำนักงาน');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (50,1,'(2) ปฏิบัติตามมาตรการที่ได้กำหนดใน ข้อ (1) ถ้าพบว่ามีเสียงดังที่มาจากภายในสำนักงาน');
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (51,19,'5.3.2','การจัดการเสียงดังจากการก่อสร้าง ปรับปรุงอาคารหรืออื่นๆ ในสำนักงานที่ส่งผลต่อพนักงาน',1);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (51,0,'(1) กำหนดมาตรการรองรับเพื่อจัดการเสียงดังที่เกิดจากการก่อสร้างปรับปรุงอาคาร');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (51,1,'(2) ปฏิบัติตามมาตรการที่ได้กำหนดใน ข้อ (1)แนวทางการกำหนดมาตรการมีดังนี้- มีพื้นที่ทำงานสำรองให้กับพนักงาน- มีการสื่อสารหรือติดป้ายแจ้งเตือน เพื่อการเตรียมความพร้อมและระวังการได้รับอันตราย');
INSERT INTO criteria_issues (id, category_id, code, title, sort) VALUES (20,5,'5.4','ความน่าอยู่',3);
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (52,20,'5.4.1','มีการวางแผนจัดการความน่าอยู่ของสำนักงานโดยจะต้องดำเนินการ ดังนี้',0);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (52,0,'(1) จัดทำแผนผังของสำนักงานทั้งในตัวอาคารและนอกอาคาร โดยจะต้องกำหนดพื้นที่ใช้งานอย่างชัดเจน เช่น พื้นที่พักผ่อนหย่อนใจ พื้นที่สีเขียว พื้นที่ส่วนรวม และพื้นที่ทำงาน เป็นต้น สามารถสื่อสารด้วยป้ายหรืออื่น ๆ ที่เหมาะสมเพื่อบ่งชี้');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (52,1,'(2) มีการกำหนดหน้าที่ความรับผิดชอบอย่างเหมาะสมทั้งพื้นที่เฉพาะ และพื้นที่ทั่วไป ทั้งในอาคารและนอกอาคาร');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (52,2,'(3) มีการกำหนดเวลาในการดูแลรักษาความสะอาดและความเป็นระเบียบเรียบร้อย ทั้งพื้นที่เฉพาะ และพื้นที่ทั่วไป ทั้งในอาคารและนอกอาคาร');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (52,3,'(4) การกำหนดแผนงานการเพิ่มพื้นที่สีเขียว และคงรักษาไว้ของสำนักงาน รวมไปถึงมีการปฏิบัติจริงตามแผนงาน');
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (53,20,'5.4.2','ร้อยละการใช้สอยพื้นที่เป็นไป ตามวัตถุประสงค์ที่สำนักงานกำหนด',1);
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (54,20,'5.4.3','ร้อยละการดูแลบำรุงรักษาพื้นที่ต่าง ๆ เช่น พื้นที่สีเขียว พื้นที่ พักผ่อนหย่อนใจ พื้นที่ส่วนกลาง และพื้นที่ทำงาน เป็นต้น',2);
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (55,20,'5.4.4','มีการควบคุมสัตว์พาหะนำโรค และดำเนินการได้ตามที่กำหนด',3);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (55,0,'(1) มีการกำหนดแนวทางการป้องกันสัตว์พาหะนำโรคในสำนักงานอย่างเหมาะสม ได้แก่ นกพิราบ หนู แมลงสาบ และอื่น ๆ');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (55,1,'(2) มีการกำหนดความถี่ในการตรวจสอบร่องรอยสัตว์พาหะนำโรคอย่างน้อยที่สุดเดือนละ 1 ครั้ง');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (55,2,'(3) มีการตรวจสอบร่องรอยตามความถี่ที่ได้กำหนด (เฉพาะตอนกลางวัน)');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (55,3,'(4) มีแนวทางที่เหมาะสมกับการจัดการเมื่อพบร่องรอยสัตว์พาหะนำโรค');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (55,4,'(5) ไม่พบร่องรอยหรือสัตว์พาหะนำโรคในระหว่างการตรวจประเมิน');
INSERT INTO criteria_issues (id, category_id, code, title, sort) VALUES (21,5,'5.5','การเตรียมพร้อมต่อสภาวะฉุกเฉิน',4);
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (56,21,'5.5.1','การอบรมฝึกซ้อมดับเพลิงและอพยพหนีไฟตามแผนที่กำหนด',0);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (56,0,'(1) มีการกำหนดแผนการฝึกอบรมและอพยพหนีไฟ');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (56,1,'(2) จำนวนคนเข้าอบรมฝึกซ้อมดับเพลิงขั้นต้นจะต้องไม่ต่ำกว่าร้อยละ 40ของพนักงานแต่ละแผนกหรือส่วนงาน');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (56,2,'(3) พนักงานทุกคนจะต้องเข้าฝึกซ้อมอพยพหนีไฟ อย่างน้อยปีละ 1 ครั้ง (พิจารณาพนักงานหรือผู้ปฏิบัติงานทุกคนที่อยู่ประจำพื้นที่สำนักงานที่มีการฝึกซ้อมเท่านั้น)');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (56,3,'(4) มีการอบรมดับเพลิงขั้นต้นตามแผนที่กำหนด พร้อมแสดงหลักฐาน เช่น ใบรับรองการอบรม ภาพถ่าย เป็นต้น');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (56,4,'(5) มีการฝึกซ้อมอพยพตามแผนที่กำหนด พร้อมแสดงหลักฐาน เช่น ใบรับรอง ภาพถ่าย เป็นต้น');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (56,5,'(6) มีการกำหนดจุดรวมพลที่สามารถรองรับได้ พร้อมมีป้ายแสดงอย่างชัดเจน');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (56,6,'(7) มีการกำหนดเส้นทางหนีไฟ ธงนำทางหนีไฟไปยังจุดรวมพล พร้อมสื่อสารในพื้นที่ปฏิบัติงาน');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (56,7,'(8) มีการกำหนดทางออกฉุกเฉิน ทางหนีไฟ พร้อมมีป้ายแสดงอย่างชัดเจน');
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (57,21,'5.5.2','มีแผนฉุกเฉินที่เป็นปัจจุบันและเหมาะสม และร้อยละของพนักงานที่เข้าใจแผนฉุกเฉิน',1);
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (58,21,'5.5.3','ความเพียงพอและการพร้อมใช้งานของอุปกรณ์ระบบดับเพลิงและป้องกันอัคคีภัย และระบบสัญญาณแจ้ง เหตุเพลิงไหม้ และร้อยละของพนักงาน ทราบวิธีการใช้และตรวจสอบอุปกรณ์ดังกล่าว',2);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (58,0,'(1) มีการติดตั้งและเตรียมอุปกรณ์ดับเพลิง- ถังดับเพลิงมีเพียงพอต่อการใช้งาน (กำหนดระยะห่าง อย่างน้อย 20 เมตร/ถัง ตามกฎหมาย ติดตั้งสูงจากพื้นไม่เกิน 150เซนติเมตรนับจากคันบีบ และถ้าเป็นวางกับพื้นจะต้องมีฐานรองรับ) พร้อมกับติดป้ายแสดง- ติดตั้งระบบเครื่องสูบน้ำดับเพลิง (ถ้ามี)- สายฉีดน้ำดับเพลิงและตู้เก็บสายฉีด ( Hose and Hose Station) (ถ้ามี)');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (58,1,'(2) ติดตั้งระบบสัญญาณแจ้งเตือนและต้องพร้อมใช้งาน- สัญญาณแจ้งเหตุเพลิงไหม้ (พื้นที่มากกว่า 300 ตารางเมตรหรืออาคารสูงเกิน 2 ชั้นขึ้นไป)- ติดตั้งตัวดักจับควัน (smoke detector) หรือตัวตรวจจับความร้อน (heat detector)');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (58,2,'(3) มีการตรวจสอบข้อ (1) - (2) และหากพบว่าชำรุดจะต้องดำเนินการแจ้งซ่อมและแก้ไข');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (58,3,'(4) พนักงานจะต้องเข้าใจถึงวิธีการใช้และตรวจสอบอุปกรณ์ดับเพลิงและสัญญาณแจ้งเตือน อย่างน้อยร้อยละ 75 จากที่สุ่มสอบถาม');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (58,4,'(5) ไม่มีสิ่งกีดขวางอุปกรณ์ดับเพลิง และสัญญาณแจ้งเหตุเพลิงไหม้');
INSERT INTO criteria_issues (id, category_id, code, title, sort) VALUES (22,6,'6.1','การจัดซื้อสินค้า',0);
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (59,22,'6.1.1','การจัดซื้อสินค้าที่เป็นมิตรกับสิ่งแวดล้อม',0);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (59,0,'(1) กำหนดผู้รับผิดชอบและมีความเข้าใจ');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (59,1,'(2) ค้นหารายการสินค้าที่เป็นมิตรกับสิ่งแวดล้อม และสามารถระบุแหล่งข้อมูลสืบค้นได้');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (59,2,'(3) จัดทำบัญชีรายชื่อสินค้าที่เป็นมิตรกับสิ่งแวดล้อมที่สอดคล้องกับสินค้าที่ใช้จริงในสำนักงาน โดยจะต้องระบุรายการสินค้า ยี่ห้อ ฉลากสิ่งแวดล้อม วันหมดอายุ การรับรองของสินค้านั้น หากเป็นฉลากสิ่งแวดล้อมของต่างประเทศ จะต้องอ้างอิงหน่วยงาน/ประเทศที่ให้การรับรองนั้นๆ ด้วย');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (59,3,'(4) แจ้งไปยังผู้ขายเพื่อขอความร่วมมือในการสั่งซื้อสินค้าที่เป็นมิตรกับสิ่งแวดล้อม กรณีที่ไม่มีร้านค้าที่จำหน่ายสินค้าทีเป็นมิตรกับสิ่งแวดล้อม');
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (60,22,'6.1.2','ร้อยละของการจัดซื้อสินค้าประเภทวัสดุอุปกรณ์ในสำนักงานที่เป็นมิตรกับสิ่งแวดล้อมหมายเหตุ:ร้อยละของสินค้าที่เป็นมิตรกับสิ่งแวดล้อมจะเทียบกับปริมาณการซื้อ และ/หรือ มูลค่าสินค้า',1);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (60,0,'(1) แสดงรายการสินค้าสำนักงานที่จัดซื้อทั้งหมด โดยระบุยี่ห้อและรุ่นสินค้า');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (60,1,'(2) แสดงฉลากที่เป็นมิตรกับสิ่งแวดล้อมของสินค้า');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (60,2,'(3) คำนวณจำนวนร้อยละสินค้าที่เป็นมิตรกับสิ่งแวดล้อม โดยจะต้องแสดงให้เห็นถึงรายการสินค้า ปริมาณสินค้า และมูลค่าหมายเหตุ:สินค้าที่เป็นมิตรกับสิ่งแวดล้อมจะต้องเป็นสินค้าที่ได้รับการรับรองจากสถาบันที่เป็นที่ยอมรับ เช่น ฉลากเขียว ตะกร้าเขียว ฉลากประหยัดไฟเบอร์ 5ฉลากประสิทธิภาพสูง ฉลากคาร์บอนฟุตปริ้นท์ ฉลากลดโลกร้อน สินค้า OTOP ที่มีเลขจดทะเบียน ฉลากสิ่งแวดล้อมของต่างประเทศ เป็นต้น');
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (61,22,'6.1.3','ร้อยละของปริมาณและประเภทของวัสดุอุปกรณ์ในสำนักงานที่เป็นมิตรกับสิ่งแวดล้อมหมายเหตุ:สินค้าที่เป็นมิตรกับสิ่งแวดล้อมจะต้องเป็นสินค้าที่ได้รับการรับรองจากสถาบันที่เป็นที่ยอมรับ เช่น ฉลากเขียว ตะกร้าเขียว ฉลากประหยัดไฟ เบอร์ 5ฉลากประสิทธิภาพสูง ฉลากคาร์บอนฟุตปริ้นท์ ฉลากลดโลกร้อน สินค้า OTOP ที่มีเลขจดทะเบียน ฉลากสิ่งแวดล้อมของต่างประเทศ เป็นต้น',2);
INSERT INTO criteria_issues (id, category_id, code, title, sort) VALUES (23,6,'6.2','การจัดจ้าง',1);
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (62,23,'6.2.1','ร้อยละของการจัดจ้างหน่วยงานหรือบุคคลที่มีการดำเนินงานที่เป็นมิตรกับสิ่งแวดล้อม',0);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (62,0,'(1) มีหลักฐานการพิจารณาถึงมาตรฐานด้านสิ่งแวดล้อมของหน่วยงานที่ได้การรับรองโดยจะต้องแสดงหลักฐานการรับรองดังกล่าว');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (62,1,'(2) หากหน่วยงานไม่มีมาตรฐานด้านสิ่งแวดล้อมรับรอง ทางสำนักงานจะต้องทำการประเมินด้านสิ่งแวดล้อมของหน่วยเบื้องต้น');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (62,2,'(3) มีการจัดทำสัญญาหรือข้อตกลงด้านสิ่งแวดล้อม เมื่อเข้ามาปฏิบัติงานในสำนักงาน');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (62,3,'(4) หน่วยงานหรือบุคคลที่ได้รับคัดเลือกจะต้องได้รับการอบรมหรือสื่อสารเกี่ยวกับสำนักงานสีเขียว และแนวทางการจัดการสิ่งแวดล้อมที่เกี่ยวข้องกับกิจกรรมของตนเอง');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (62,4,'(5) หน่วยงานหรือบุคคลเหล่านั้นสามารถอธิบายแนวทางในการจัดการสิ่งแวดล้อมที่เกี่ยวข้องกับกิจกรรมของตนเองได้หมายเหตุ:สินค้าที่เป็นมิตรกับสิ่งแวดล้อมจะต้องเป็นสินค้าที่ได้รับการรับรองจากสถาบันที่เป็นที่ยอมรับ เช่น ฉลากเขียว ตะกร้าเขียว ฉลากประหยัดไฟ เบอร์ 5ฉลากประสิทธิภาพสูง ฉลากคาร์บอนฟุตปริ้นท์ ฉลากลดโลกร้อน สินค้า OTOP ที่มีเลขจดทะเบียน ฉลากสิ่งแวดล้อมของต่างประเทศ เป็นต้น');
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (63,23,'6.2.2','ร้อยละของการตรวจสอบด้านการดูแลสิ่งแวดล้อมในพื้นที่ปฏิบัติงานของหน่วยงาน หรือบุคคลที่เข้ามาดำเนินการ เช่น ผู้รับจ้าง ผู้รับจ้างช่วงแม่บ้าน รปภ. พนักงานส่งเอกสาร เป็นต้นหมายเหตุ:',1);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (63,0,'(1) สถานที่ที่ได้รับการรับรองมาตรฐานการจัดการสิ่งแวดล้อมที่ดี เช่น ISO 14001 Green Hotel ใบไม้เขียว ฉลากเขียว Green Officeหรือ Green Building เป็นต้น และมีการจัดประชุมที่คำนึงถึงการอนุรักษ์ทรัพยากรธรรมชาติและพลังงาน และลดการก่อให้เกิดมลพิษ');
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (63,1,'(2) ในกรณีที่ไม่มีสถานที่จัดประชุมที่ได้รับการรับรองฯ อยู่ในบริเวณใกล้เคียงสำนักงานจะต้องเลือกสถานที่ที่ใช้เวลาเดินทางน้อยที่สุด และจัดประชุมในรูปแบบGreen Meeting (ตามความเหมาะสมและเป็นไปได้)');
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (64,23,'6.2.3','การเลือกใช้บริการโรงแรมที่เป็นมิตรกับสิ่งแวดล้อม (นอกสำนักงาน) ได้แก่ โรงแรม สถานที่จัดงานหรืออื่นๆ ที่ได้มีการขึ้นทะเบียน การบริการที่เป็นมิตรกับสิ่งแวดล้อมหมายเหตุ:- กรณีที่เป็นการว่าจ้างให้อยู่ประจำสำนักงานจะต้องทำการประเมินอย่างน้อยเดือนละ 1 ครั้ง- กรณีที่เป็นการว่าจ้างไม่อยู่ประจำสำนักงานจะต้องทำการประเมินทุกครั้งเมื่อเข้ามาปฏิบัติงานในสำนักงาน',2);
INSERT INTO criteria_issues (id, category_id, code, title, sort) VALUES (24,7,'7.1','การตรวจประเมินสำนักงานสีเขียวเพื่อให้เกิดการปรับปรุงอย่างต่อเนื่อง',0);
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (65,24,'7.1.1','มีการแต่งตั้งคณะกรรมการตรวจ ประเมินสำนักงานสีเขียวภายในสำนักงาน ประกอบด้วย หัวหน้าผู้ตรวจประเมินและ ผู้ตรวจประเมิน ซึ่งจะต้องผ่านการ ฝึกอบรมหลักสูตรการดำเนินงาน สำนักงานสีเขียว หรือหลักสูตรด้านการ จัดการสิ่งแวดล้อมและพลังงานที่ เกี่ยวข้อง และหลักสูตรการตรวจประเมิน สำนักงานสีเขียว หรือหลักสูตรการตรวจ ประเมินการจัดการสิ่งแวดล้อม เช่น ISO 14001',0);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (65,0,'(1) มีการแต่งตั้งคณะกรรมการตรวจ ประเมินสำนักงานสีเขียวภายในสำนักงาน ประกอบด้วย หัวหน้าผู้ตรวจประเมินและ ผู้ตรวจประเมิน ซึ่งจะต้องผ่านการ ฝึกอบรมหลักสูตรการดำเนินงาน สำนักงานสีเขียว หรือหลักสูตรด้านการ จัดการสิ่งแวดล้อมและพลังงานที่ เกี่ยวข้อง และหลักสูตรการตรวจประเมิน สำนักงานสีเขียว หรือหลักสูตรการตรวจ ประเมินการจัดการสิ่งแวดล้อม เช่น ISO 14001');
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (66,24,'7.1.2','มีการกำหนดความถี่ในการตรวจ ประเมินสำนักงานสีเขียวภายในสำนักงาน อย่างน้อยปีละ 1 ครั้ง',1);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (66,0,'(2) มีการกำหนดความถี่ในการตรวจประเมินสำนักงานสีเขียวภายในสำนักงาน อย่างน้อยปีละ 1 ครั้ง');
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (67,24,'7.1.3','มีการจัดทำข้อกำหนดการตรวจประเมินภายในครอบคลุมทุกหมวด',2);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (67,0,'(3) มีการจัดทำข้อกำหนดการตรวจประเมินภายในครอบคลุมทุกหมวด');
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (68,24,'7.1.4','กำหนดผู้ตรวจประเมินภายในแต่ละหมวดมีความเพียงพอและเหมาะสม มีความเป็นอิสระในการตรวจประเมินอย่างชัดเจน',3);
