INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (69,24,'7.1.5','การดำเนินการตรวจประเมินสำนักงานสีเขียวภายในสำนักงานครบถ้วนทุกหมวด และสรุปผลการตรวจประเมิน',4);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (69,0,'(5) การดำเนินการตรวจประเมินสำนักงานสีเขียวภายในสำนักงานครบถ้วนทุกหมวด และสรุปผลการตรวจประเมิน');
INSERT INTO criteria_issues (id, category_id, code, title, sort) VALUES (25,7,'7.2','การพัฒนาหรือต่อยอดการดำเนินงานสำนักงานสีเขียว',1);
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (70,25,'7.2.1','การต่อยอดจากสำนักงานสีเขียวไปสู่รางวัล หรือการรับรองด้านสิ่งแวดล้อม หรือมาตรฐานด้านสิ่งแวดล้อม หรือพลังงาน หรืออื่นๆ ที่มีหน่วยงานกลางให้การรับรอง เช่น คาร์บอนฟุตพริ้นท์ขององค์กร (Carbon Footprint for Organization) ISO 14001 มาตรฐานระบบการจัดการสิ่งแวดล้อม (Environment management System) เป็นต้น',0);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (70,0,'(1) การต่อยอดจากสำนักงานสีเขียวไปสู่รางวัล หรือการรับรองด้านสิ่งแวดล้อม หรือมาตรฐานด้านสิ่งแวดล้อม หรือพลังงาน หรืออื่นๆ ที่มีหน่วยงานกลางให้การรับรองเช่น คาร์บอนฟุตพริ้นท์ขององค์กร (Carbon Footprint for Organization) ISO 14001 มาตรฐานระบบการจัดการสิ่งแวดล้อม (Environment management System) เป็นต้น');
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (71,25,'7.2.2','ส่งเสริมการดำเนินงานสำนักงานสีเขียวให้กับหน่วยงานที่สนใจเข้าร่วมโครงการ เช่น การเป็นวิทยากรให้คำแนะนำ สถานที่ศึกษาดูงานให้กับหน่วยงาน เป็นต้น',1);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (71,0,'(2) ส่งเสริมการดำเนินงานสำนักงานสีเขียวให้กับหน่วยงานที่สนใจเข้าร่วมโครงการ เช่น การเป็นวิทยากรให้คำแนะนำ สถานที่ศึกษาดูงานให้กับหน่วยงาน เป็นต้น');
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (72,25,'7.2.3','สร้างเครือข่ายในการดำเนินงานสำนักงานสีเขียว โดยเป็นทีมพี่เลี้ยง Coaching ให้คำแนะนำ ให้ความรู้เพื่อเตรียมความพร้อมสำหรับหน่วยงานใหม่ที่จะขอการรับรองสำนักงานสีเขียว',2);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (72,0,'(3) สร้างเครือข่ายในการดำเนินงานสำนักงานสีเขียว โดยเป็นทีมพี่เลี้ยง Coaching ให้คำแนะนำ ให้ความรู้เพื่อเตรียมความพร้อมสำหรับหน่วยงานใหม่ที่จะขอการรับรองสำนักงานสีเขียว');
INSERT INTO criteria_indicators (id, issue_id, code, title, sort) VALUES (73,25,'7.2.4','กดำเนินกิจกรรมที่มีส่วนร่วมชุมชน หรือหน่วยงานภายนอก ในการอนุรักษ์ทรัพยากรธรรมชาติและสิ่งแวดล้อมหรือการเปลี่ยนแปลงสภาพภูมิอากาศ เช่น การเพิ่มพื้นที่สีเขียว',3);
INSERT INTO criteria_subitems (indicator_id, idx, text) VALUES (73,0,'(4) ดำเนินกิจกรรมที่มีส่วนร่วมชุมชนหรือหน่วยงานภายนอก ในการอนุรักษ์ทรัพยากรธรรมชาติและสิ่งแวดล้อมหรือการเปลี่ยนแปลงสภาพภูมิอากาศ เช่น การเพิ่มพื้นที่สีเขียว');
