INSERT INTO complaints (ticket_no, type, topic, place, detail, status, result_text, is_public, public_title, public_detail) VALUES ('GO-2569-001','ข้อร้องเรียน','ไฟฟ้า / พลังงาน','','ไฟทางเดินชั้น 3 อาคาร [x] เปิดทิ้งไว้หลังเวลาทำการเป็นประจำ','done','ติดตั้งสวิตช์ตั้งเวลาปิดอัตโนมัติ 20.00 น. และติดป้ายรณรงค์',1,'ไฟทางเดินชั้น 3 เปิดทิ้งช่วงกลางคืน','ไฟทางเดินชั้น 3 อาคาร [x] เปิดทิ้งไว้หลังเวลาทำการเป็นประจำ');
INSERT INTO complaints (ticket_no, type, topic, place, detail, status, result_text, is_public, public_title, public_detail) VALUES ('GO-2569-002','ข้อร้องเรียน','ขยะ / ของเสีย','','ถังขยะรีไซเคิลบริเวณโรงอาหารเต็มก่อนรอบจัดเก็บ ทำให้มีการทิ้งปนกับขยะทั่วไป','fixing','อยู่ระหว่างประสานเพิ่มรอบจัดเก็บและเพิ่มถัง',1,'ถังขยะรีไซเคิลหน้าโรงอาหารล้น','ถังขยะรีไซเคิลบริเวณโรงอาหารเต็มก่อนรอบจัดเก็บ ทำให้มีการทิ้งปนกับขยะทั่วไป');
INSERT INTO complaints (ticket_no, type, topic, place, detail, status, result_text, is_public, public_title, public_detail) VALUES ('GO-2569-003','ข้อร้องเรียน','อากาศ / กลิ่น','','มีกลิ่นรบกวนจากจุดพักขยะในช่วงบ่าย โดยเฉพาะวันที่อากาศร้อน','received','',1,'กลิ่นจากจุดพักขยะใกล้อาคาร [x]','มีกลิ่นรบกวนจากจุดพักขยะในช่วงบ่าย โดยเฉพาะวันที่อากาศร้อน');
